import type { Player } from './index';

export const coach = 'Hong Myung-bo';
export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Kim Seung-gyu', position: 'GK', age: 35, club: 'FC Tokyo', bio: {"es":"Decidió convertirse en futbolista a los ocho años después de quedar cautivado por el legendario portero surcoreano Kim Byung-ji, quien anotó un famoso cabezazo durante un playoff de la Liga K. Su padre lo disuadió de convertirse en portero al principio, y sus primeros años los pasó en el jardín, pero, cuando cambió, nunca miró hacia atrás. Pasó tres años en la Saudi Pro League con Al-Shabab antes de mudarse a Tokio el año pasado. Nombró a Lee Woon-jae, héroe de la Copa Mundial de 2002 y mayor rival de Kim Byung-ji, como su modelo a seguir y, así como la rivalidad entre Kim y Lee definió una era para la selección nacional, ha pasado la última década como un feroz rival por el puesto número uno nacional con su amigo Jo Hyeon-woo. En mayo de 2024, Kim se casó con la supermodelo surcoreana Kim Jin-kyung.","en":"Decided to become a footballer aged eight after being captivated by the legendary South Korean keeper Kim Byung-ji, who famously scored a header during a K League playoff. His dad discouraged him from becoming a keeper at first, and his early years were all spent outfield, but, when he switched, he never looked back. He spent three years in the Saudi Pro League with Al-Shabab before moving to Tokyo last year. He named Lee Woon-jae – hero of the 2002 World Cup and Kim Byung-ji’s greatest rival – as his role model, and, just as the Kim-Lee rivalry defined an era for the national side, he has spent the last decade as a fierce rival for the national No 1 spot with his friend Jo Hyeon-woo. In May 2024, Kim married South Korean supermodel Kim Jin-kyung."} },
  { number: 12, name: 'Song Bum-keun', position: 'GK', age: 28, club: 'Jeonbuk Hyundai Motors', bio: {"es":"Song se convirtió en el portero titular del Jeonbuk Hyundai Motors, campeón de la K League 1, con sólo 21 años, y desde entonces ha levantado el título cinco veces. Pero, debido a que su compañero de equipo internacional Jo Hyeon-woo jugaba en la misma división, no fue hasta el año pasado que finalmente se ganó un lugar en el XI Mejor de la K League 1 como el mejor portero de la liga. Muy respetado por su excelente distribución y compostura en el uno contra uno, tiene un gran futuro en la selección nacional. Su nombre se inspiró en la leyenda del fútbol surcoreano Cha Bum-kun, dos veces ganador de la Copa de la UEFA, ya que su padre era un gran admirador. Esto también llevó a su apodo \"Song-boom\", un juego de palabras con el apodo de Cha, \"Cha-boom\".","en":"Song became the starting keeper for K League 1 champions Jeonbuk Hyundai Motors at the age of just 21, and has since lifted the title five times. But, due to international teammate Jo Hyeon-woo playing in the same division, it wasn't until last year that he finally earned a spot in the K League 1 Best XI as the league's top keeper. Well respected for his excellent distribution and composure in one-on-one situations, he has a big future with the national side. His name was inspired by the South Korean football legend Cha Bum-kun, a two-time Uefa Cup winner, as his father was a big fan. This also led to his nickname “Song-boom”, a play on Cha's nickname, “Cha-boom”."}, special: "Good distribution" },
  { number: 21, name: 'Jo Hyeon-woo', position: 'GK', age: 34, club: 'Ulsan HD FC', bio: {"es":"Jo saltó al estrellato con una heroica portería a cero contra Alemania en el Mundial de 2018, un partido conocido como el Milagro de Kazán en Corea. Más tarde le restó importancia y dijo: \"No fui yo, sino toda la nación la que se unió para bloquearlos. Nos defendimos como una sola nación\". En los años transcurridos desde entonces, se ha convertido en un pilar clave del equipo nacional junto a su rival por el puesto número uno, Kim Seung-gyu. Reconocido por sus reflejos de élite y estabilidad aérea, tiene dos apodos: \"Dae-Gea\", una mezcla de su antiguo club Daegu y el jugador con el que a menudo se le compara, David De Gea, y Bit-Hyeon-woo, que significa \"Shining Hyeon-woo\", lo que lo convierte en el salvador del país. Hablando el año pasado, dijo que la Copa del Mundo era “una oportunidad para que más gente supiera sobre un portero llamado Jo Hyeon-woo… Estoy un poco nervioso… Creo que me iré de Corea con el corazón acelerado”.","en":"Jo rose to stardom with a heroic clean sheet against Germany in the 2018 World Cup, a match known as the Miracle of Kazan in Korea. He played it down later, saying: “It wasn't me, but the whole nation that stood together to block them. We defended as one nation.\" In the years since he has become a key pillar of the national team alongside his rival for the No 1 spot, Kim Seung-gyu. Renowned for his elite reflexes and aerial stability, he has two nicknames: “Dae-Gea” - a mix of his former club Daegu and the player he’s often compared to, David De Gea - and Bit-Hyeon-woo, meaning “Shining Hyeon-woo”, casting him the country’s saviour. Speaking last year he said the World Cup was “an opportunity to let more people know about a goalkeeper named Jo Hyeon-woo … I'm a little nervous … I think I'll leave Korea with a fluttering heart.”"} },
  // Defensores
  { number: 2, name: 'Lee Han-beom', position: 'DF', age: 23, club: 'FC Midtjylland', bio: {"es":"Graduado del FC Seúl, la carrera de Lee despegó después de mudarse a Dinamarca en 2023 con el FC Midtjylland, donde su progreso le valió un lugar en la selección absoluta de Corea del Sur. Si bien sus oportunidades internacionales han sido esporádicas hasta ahora, su imponente perfil físico y su excelente lectura del juego han hecho que muchos lo consideren un posible sucesor de Kim Min-jae. Ganó el oro en los Juegos Asiáticos de Hangzhou de 2022, que le otorgaron una exención del servicio militar obligatorio. El año pasado habló sobre dónde necesita desarrollarse y le dijo a Fifa.com: \"Lo que me falta es agresividad en mi juego. Cuando estamos en el campamento de la selección nacional, Kim Min-jae a menudo me dice: 'Los centrales deben ser duros'. He estado tratando de cumplir con esa expectativa, pero creo que todavía es un trabajo en progreso, aunque creo que he mejorado bastante en ese área\".","en":"An FC Seoul graduate, Lee’s career took off after 2023’s move to Denmark with FC Midtjylland, where his progress earned him a spot in the South Korea senior set-up. While his international chances have been sporadic so far, his imposing physical profile and fine reading of the game have had plenty eyeing him as a potential successor to Kim Min-jae. He won gold at the 2022 Hangzhou Asian Games, which provided an exemption from mandatory military service. He spoke last year about where he needs to develop, telling Fifa.com: “What I lack is aggression in my play. When we’re in national team camp, Kim Min-jae often tells me: ‘Centre-backs need to be rough’. I’ve been trying to meet that expectation, but I think it’s still a work in progress, although I believe that I’ve improved in that area quite a bit.”"} },
  { number: 3, name: 'Lee Ki-hyuk', position: 'DF', age: 25, club: 'Gangwon FC', bio: {"es":"En una selección final de plantilla que ofreció pocas sorpresas, la inclusión del defensor se destaca como el único y genuino comodín. Cómodo en la posesión, Lee, zurdo, es útil para construir desde atrás y tiene una disposición natural para avanzar, lo que significa que también se espera que brinde cobertura como mediocampista defensivo. Lee ingresó por primera vez a las filas profesionales como mediocampista pero, según la mayoría de las cuentas, era una figura periférica. Sin embargo, después de mudarse a Gangwon, el técnico Yoon Jong-hwan lo convirtió en defensor, una decisión que impulsó su carrera hacia adelante, transformándolo en uno de los mejores centrales de la Liga K. Lee fue llamado a filas por Corea del Sur y tuvo que hacer algunos deberes: \"Quiero observar de cerca a Hwang In-beom y aprender todo lo que pueda de él\", dijo. Curiosamente, su modelo futbolístico infantil fue el hombre utilitario del Manchester United, John O'Shea. Fuera del campo, Lee cuenta con una experiencia atlética diversa como cinturón negro de Taekwondo.","en":"In a final squad selection that offered few surprises, the defender’s inclusion stands out as the solitary, genuine wildcard. Comfortable in possession, the left-footed Lee is handy in building from the back and has a natural willingness to drive forward, meaning he is also expected to provide cover as a defensive midfielder. Lee first entered the professional ranks as a midfielder but was, by most accounts, a peripheral figure. However, after moving to Gangwon, manager Yoon Jong-hwan converted him into a defender – a decision that propelled his career forward, transforming him into one of the K League’s finest centre-backs. Lee was called up by South Korea and had to do some homework: \"I want to watch Hwang In-beom closely and learn as much as I can from him,\" he said. Interestingly, his childhood footballing blueprint was Manchester United’s utility man John O’Shea. Off the pitch, Lee boasts a diverse athletic background as a Taekwondo black belt."}, special: "Fan of John O'Shea" },
  { number: 4, name: 'Kim Min-jae', position: 'DF', age: 29, club: 'Bayern Munich', captain: true, bio: {"es":"Ampliamente considerado como el mejor central de Asia, “El Monstruo” obtiene su físico de su padre entrenado en judo y su ritmo de su madre, una atleta de atletismo. La carrera de Kim en el club ha sido estelar: en 2023 fue nombrado mejor defensor de la Serie A cuando jugaba en el Napoli, cuyo entrenador Luciano Spalletti dijo: \"Hace al menos 20 cosas increíbles por partido. Cuando corre con el balón en los pies, en cinco segundos está dentro del área rival\". Poco después de ese premio, se mudó al Bayern de Múnich por 43 millones de libras, compaginando eso con completar su servicio militar obligatorio. La medida le convirtió en el futbolista asiático más caro de todos los tiempos. Después del Mundial de 2022, Son Heung-min anunció durante una cena que Kim era el jugador más atractivo del equipo. Kim respondió: \"No confío en la gente que dice que soy guapo\".","en":"Widely regarded as Asia’s finest centre-back, “The Monster” gets his physicality from his judo-trained dad and his pace from his mum, a track and field athlete. Kim’s club career has been stellar: in 2023 he was named Serie A’s best defender when playing for Napoli, whose coach Luciano Spalletti said: “He does at least 20 unbelievable things per game. When he runs with the ball at his feet, he's inside the opposition penalty area within five seconds.\" Soon after that award he made a £43m move to Bayern Munich, juggling that with completing his compulsory military service. The move made him the most expensive Asian footballer of all time. After the 2022 World Cup, Son Heung-min announced during a dinner that Kim was the side’s best-looking player. Kim responded: “I don’t trust people who say I’m handsome.”"}, special: "Defensive rock" },
  { number: 5, name: 'Kim Tae-hyeon', position: 'DF', age: 25, club: 'Kashima Antlers', bio: {"es":"Un central zurdo cuyo impresionante estado de forma en la J-League le valió una primera convocatoria el verano pasado y, finalmente, un lugar en este equipo de la Copa del Mundo. Se habría mudado a Japón mucho antes después de que se llegara a un acuerdo con Vegalta Sendai en diciembre de 2021, pero la transferencia se estancó debido a Covid. Sin embargo, revivió al año siguiente y, después de un período exitoso allí, se unió a Sagan Tosu en 2024 y luego se mudó al actual club Kashima Antlers el año pasado. En el equipo se le conoce cariñosamente como \"Swings\", gracias a su parecido con el rapero surcoreano.","en":"A left-footed centre-back whose impressive form in the J-League earned him a first call-up last summer, and ultimately a place in this World Cup squad. He would have moved to Japan much sooner after a deal was agreed with Vegalta Sendai in December 2021, but the transfer stalled due to Covid. It was revived the following year, though, and after a successful spell there he joined Sagan Tosu in 2024, then moved to current club Kashima Antlers last year. He’s affectionately known as “Swings” in the squad, thanks to his resemblance to the South Korean rapper."} },
  { number: 13, name: 'Lee Tae-seok', position: 'DF', age: 23, club: 'Austria Wien', bio: {"es":"A menudo se describe a Lee como el reflejo de su padre, Lee Eul-yong, parte del equipo de Corea del Sur en la Copa Mundial de 2002. No es sólo el sorprendente parecido físico: también tiene el refinado pie izquierdo de su padre. ¿Entonces es mejor que su padre? “Todavía no, pero estoy llegando a ese punto”, dijo el año pasado. El padre de Lee tardó en florecer, pero el progreso de su hijo ha sido rápido: consiguió tanto su debut internacional como su traslado al extranjero a una edad significativamente más temprana. Con Hong Myung-bo ha consolidado su lugar como lateral izquierdo titular de la selección nacional, donde viste la camiseta número 13, la misma que llevaba su padre. Lee dijo en 2025: \"Las cosas que solo soñé el año pasado se han hecho realidad este año: transferirme a Europa y jugar regularmente para la selección nacional. Mi próximo objetivo es representar a Corea en la Copa del Mundo. Seguiré esforzándome\".","en":"Lee is often described as the mirror image of his father, Lee Eul-yong, part of South Korea’s 2002 World Cup side. It’s not just the striking physical resemblance: he also has his father’s cultured left foot. So is he better than his dad? “Not yet, but I’m getting there,” he said last year. The elder Lee was a late bloomer but his son’s progress has been fast: he secured both his international debut and a move abroad at a significantly younger age. Under Hong Myung-bo he has cemented his place as the national team’s first-choice left-back, where he wears the No 13 shirt, the same worn by his father. Lee said in 2025: “Things I only dreamed of last year have come true this year – transferring to Europe and playing regularly for the national team. My next goal is to represent Korea at the World Cup. I’ll keep pushing.”"} },
  { number: 14, name: 'Cho Wi-je', position: 'DF', age: 0, club: 'Jeonbuk Hyundai Motors', bio: {"es":"Una inclusión tardía en el equipo después de que Cho Yu-min abandonara el campo de entrenamiento llorando tras romperse la fascia plantar del talón derecho pocos días antes del torneo. Al irse, Yu-min dijo: \"Quería ayudar al equipo y no pude, así que lo siento. Y lamento irme primero. Llevaré conmigo toda la mala suerte de que el equipo pueda enfrentarse a Corea y dejaré atrás solo la pasión con la que me preparé\". Cho, que fue jugador de la K League 2 (segunda división) hasta la temporada pasada, fue el beneficiario. Dijo a los periodistas en los Estados Unidos: \"Esta situación se siente surrealista e increíble. Es difícil sentirse feliz cuando mi corazón está apesadumbrado por Yu-min. Sé que no hay palabras que puedan consolar a alguien en esta situación. El buen desempeño del resto de nosotros será la mejor manera de consolarlo\". ¿En cuanto a lo que trae? \"Tengo una velocidad comparable a la de los delanteros extranjeros y sobresalgo en los duelos aéreos. La confianza me ayudará a dar lo mejor de mí\".","en":"A late, late inclusion in the squad after Cho Yu-min left the training camp in tears having torn the plantar fascia in his right heel just days before the tournament. As he left, Yu-min said: “I wanted to help the team and couldn't, so I'm sorry. And I'm sorry to be leaving first. I'll carry all the bad luck that the team may face back to Korea with me and leave behind only the passion that I prepared with.” Cho, who was a K League 2 (second tier) player until last season, was the beneficiary. He told reporters in the United States: \"This situation feels surreal and unbelievable. It’s hard to feel happy when my heart is heavy for Yu-min. I know no words can console someone in this situation. The rest of us performing well will be the best way to comfort him.\" As for what he brings? “I have speed comparable to overseas forwards and excel in aerial duels. Confidence will help me showcase my best.\""}, special: "Late call-up" },
  { number: 15, name: 'Kim Moon-hwan', position: 'DF', age: 31, club: 'Daejeon Hana Citizen', bio: {"es":"Pasó sus años de formación como delantero y permaneció allí hasta que pasó al fútbol profesional. Pero cuando se unió al Busan IPark en 2017, su potencial como lateral ofensivo quedó claro y desde entonces se ha convertido en un pilar de la selección nacional, ampliamente considerado como uno de los laterales derechos más destacados del país. Tuvo una temporada en EE. UU. con Los Angeles FC en 2021-22 y anteriormente citó a la leyenda rusa Yuri Zhirkov como su inspiración. Durante su estancia en la Universidad Chung-Ang, forjó una formidable asociación de ataque ganadora de la liga con Cho Yu-min, ahora su colega en la selección nacional, quien sufrió una metamorfosis hasta convertirse en central.","en":"Spent his formative years as a forward, and stayed there until he moved into professional football. But when he joined Busan IPark in 2017 his potential as an attacking full-back became clear, and since then he has grown into a mainstay of the national side, widely regarded as one of the pre-eminent right-backs in the country. He had a season in the US with Los Angeles FC in 2021-22, and has previously cited the Russian legend Yuri Zhirkov as his inspiration. During his time at Chung-Ang University he forged a formidable, league-winning attacking partnership with Cho Yu-min, now his national team colleague who himself underwent a metamorphosis into a centre-back."}, special: "Former forward" },
  { number: 16, name: 'Park Jin-seob', position: 'DF', age: 30, club: 'Zhejiang FC', bio: {"es":"Un verdadero tardío. Hasta los 23 años, Park jugó en la K3 League semiprofesional, pero su ascenso desde que se convirtió en profesional ha sido rápido: ganó el título de la K League 1 y obtuvo una merecida convocatoria a la selección nacional. Aporta una versatilidad útil al equipo de este verano, capaz de operar como central o mediocampista defensivo. Comparte sus iniciales en inglés, JS Park, con una leyenda surcoreana, y también es conocido por su sorprendente parecido con su compañero de equipo internacional Joo Min-kyu. Pero es un individuo sobresaliente por derecho propio. Gus Poyet, su ex manager en Jeonbuk Hyundai Motors, dijo después de ganar el título del año pasado: \"Posee un nivel de liderazgo que es raro de encontrar en cualquier parte del mundo. Para mí, Park Jin-seob es el MVP\".","en":"A real late bloomer. Until he was 23 Park played in the semi-professional K3 League, but his rise since becoming a professional has been rapid: winning the K League 1 title and earning a deserved call-up to the national side. He brings useful versatility to this summer’s squad, able to operate as a centre-back or a defensive midfielder. Shares his English initials, JS Park, with a South Korean legend, and is also known for his striking resemblance to international teammate Joo Min-kyu. But he’s very much an outstanding individual in his own right. Gus Poyet, his former manager at Jeonbuk Hyundai Motors, said after last year’s title win: \"He possesses a level of leadership that is rare to find anywhere in the world. To me, Park Jin-seob is the MVP.\""}, special: "Late bloomer" },
  { number: 22, name: 'Seol Young-woo', position: 'DF', age: 28, club: 'Red Star Belgrade', bio: {"es":"A true local icon, whose schoolboy career, university tenure and professional debut all took place in his home town, Ulsan. Un lateral versátil capaz de operar en cualquier flanco, también ha realizado sólidas actuaciones como defensa central, extremo y mediocampista central cuando fue necesario. Su desarrollo se vio obstaculizado por dislocaciones recurrentes del hombro, pero una cirugía exitosa en 2024 parece haber solucionado el problema. Finalmente dejó Ulsan en 2024 para unirse al Estrella Roja de Belgrado, y desde entonces se le ha relacionado con mudanzas a Inglaterra. A lo largo de su carrera profesional ha llevado exclusivamente el número 66, un homenaje tanto al año de nacimiento de su padre como a su admiración por Trent Alexander-Arnold.","en":"A true local icon, whose schoolboy career, university tenure and professional debut all took place in his home town, Ulsan. A versatile full-back capable of operating on either flank, he has also put in solid performances at centre-back, winger, and central midfielder when called upon. His development was being hindered by recurrent shoulder dislocations but successful surgery in 2024 appears to have fixed the issue. He finally left Ulsan in 2024 to join Red Star Belgrade, and has since been linked with moves to England. Throughout his professional career he has exclusively worn the number 66 - a tribute both to his father’s birth year and his admiration for Trent Alexander-Arnold."} },
  { number: 23, name: 'Jens Castrop', position: 'DF', age: 22, club: 'Borussia Mönchengladbach', bio: {"es":"El segundo jugador nacido en Alemania en representar al país, después de Cha Du-ri. Born to a German father and a Korean mother, he played for Germany at various youth levels before choosing to switch in August last year, and received his first South Korea call-up a month later. \"Cuando era niño, siempre supe que no era simplemente un alemán normal como los demás de mi clase\", dijo a fifa.com en marzo, y dijo que esperaba que su decisión contribuyera a \"romper barreras para una mayor diversidad en Corea\": \"Siempre supe que soy al menos mitad coreano. Eso es algo en tu carácter que ves todos los días cuando manejas ciertas situaciones. Eres un poco diferente a un niño 100% alemán. Siempre supe que era coreano y quiero ayudar al equipo y demostrarlo. otros que es posible cambiar la nación y cambiar el país”. Un jugador adaptable, ha jugado principalmente en el mediocampo de su país y como lateral del Borussia Mönchengladbach, por lo que aporta una valiosa versatilidad al equipo de este verano.","en":"The second German-born player to represent the country, after Cha Du-ri. Born to a German father and a Korean mother, he played for Germany at various youth levels before choosing to switch in August last year, and received his first South Korea call-up a month later. “Growing up I always knew I was not just a regular German like others in my class,” he told fifa.com in March, saying he hoped his decision would contribute to “breaking barriers for more diversity in Korea”: “I always knew that I'm at least half Korean. That's something in your character that you see every day as you handle certain situations. You're just a little bit kind of different than a 100% German child. I always knew I was Korean and I want to help the team and show others that it's possible to change the nation and change the country.” An adaptable performer, he has played mostly in midfield for his country and at full-back for Borussia Mönchengladbach, so brings valuable versatility to this summer’s squad."} },
  // Volantes
  { number: 6, name: 'Hwang In-beom', position: 'MF', age: 29, club: 'Feyenoord', bio: {"es":"Hwang se convirtió en una piedra angular del equipo nacional bajo la dirección de Paulo Bento, quien le dio un papel titular después de su impresionante desempeño en la carrera por la medalla de oro en los Juegos Asiáticos de 2018, y será clave para cualquier éxito que el equipo tenga este verano. Un jugador muy viajado, su carrera comenzó en Daejeon antes de mudarse a Vancouver Whitecaps, Rubin Kazan, FC Seúl, Olympiacos, Estrella Roja de Belgrado y, en 2024, al actual club Feyenoord. Un mediocampista versátil de área a área, sufrió una lesión en marzo, dañándose los ligamentos del tobillo en un partido contra Excelsior, pero se recuperó a tiempo para pasar el corte. ¿El juego de su carrera favorito hasta ahora? \"El partido de Corea contra Portugal en el último partido de la fase de grupos del Mundial de 2022, y eso nunca cambiará. Ese fue el partido más dramático que he jugado y el resultado [2-1 para Corea] me hizo la persona más feliz. Me enorgullezco de ser un futbolista que ayudó a crear un resultado que hizo feliz a toda nuestra gente en Corea\".","en":"Hwang became a cornerstone of the national team under Paulo Bento, who handed him a starting role after his impressive performance in the 2018 Asian Games gold medal run, and he will be key to any success the side has this summer. A hugely well-travelled player, his career path began in Daejeon before moves to Vancouver Whitecaps, Rubin Kazan, FC Seoul, Olympiacos, Red Star Belgrade and, in 2024, to current club Feyenoord. A versatile box-to-box midfielder, he suffered an injury scare in March, damaging ankle ligaments in a game against Excelsior, but recovered in time to make the cut. His favourite career game so far? “Korea's game against Portugal in the final World Cup group stage match in 2022, and that will never change. That was the most dramatic game that I've ever played in, and the result [2-1 for Korea] made me the happiest person. I pride myself in being a footballer who helped to create a result that made all of our people in Korea happy.”"}, special: "Key midfielder" },
  { number: 8, name: 'Paik Seung-ho', position: 'MF', age: 29, club: 'Birmingham City', bio: {"es":"Un jugador talentoso que causó sensación a los 13 años, ganó el Premio de Fútbol Cha Bum-kun al mejor prospecto joven del país y se unió a la academia La Masia de Barcelona. El peso de las expectativas era enorme, pero su progreso se vio afectado cuando la FIFA impuso una prohibición de transferencias al Barcelona por violar las reglas de transferencias y registro relativas a la contratación de jugadores internacionales menores de 18 años, impidiéndole participar en acciones competitivas durante sus años de formación. Dejó el club en 2017 por Girona, luego se mudó a Alemania con Darmstadt 98 en 2019. Regresó a Corea con Jeonbuk Hyundai Motors en 2021 antes de mudarse a Birmingham en 2024. El año pasado habló sobre el impacto que el fútbol inglés había tenido en él, diciendo en una entrevista con la Universidad de Birmingham: \"Mudarme a Inglaterra, me doy cuenta de que el fútbol significa mucho. Nunca es solo un juego, lo es todo para esta ciudad, para todos aquí. Puede deprimirte mucho, pero te da una emoción como ninguna otra cosa. Eso es lo que hace que el fútbol sea un deporte tan grande, y realmente he llegado a sentirlo así; es por eso que sigo esforzándome por jugar con todo el corazón\". Hizo su debut internacional en 2019 y marcó un brillante gol contra Brasil durante el Mundial de 2022.","en":"A gifted player who made waves aged 13, winning the Cha Bum-kun Football Award for the top young prospect in the country, and joining Barcelona’s La Masia academy. The weight of expectation was huge, but his progress was hit when Fifa imposed a transfer ban on Barcelona for breaching transfer and registration rules around signing international players aged under 18, barring him from competitive action during his formative years. He left the club in 2017 for Girona, then moved to Germany with Darmstadt 98 in 2019. He returned to Korea with Jeonbuk Hyundai Motors in 2021 before a move to Birmingham in 2024. Last year he discussed the impact English football had made on him, saying in an interview with the University of Birmingham: “Moving to England, I realise football means so much. It's never just a game - it's everything to this city, for everyone here. It can bring you down hard, but it gives you a rush like nothing else. That's what makes football such a massive sport, and I've truly come to feel that way – it's why I keep pushing to play with a full heart.\" He made his international debut in 2019, and scored a brilliant goal against Brazil during the 2022 World Cup."} },
  { number: 10, name: 'Lee Jae-sung', position: 'MF', age: 33, club: 'Mainz 05', bio: {"es":"Una auténtica leyenda de Corea del Sur con más de 100 partidos internacionales. Cambió su estatus de MVP de la K League por Alemania en 2018 y se unió al Holstein Kiel antes de mudarse al Mainz en 2021. A pesar de su esbelta figura, es un formidable especialista en el juego aéreo y un prolífico goleador con la cabeza. He knows time is catching up with him, and said in March: “It's the last and my third World Cup, but there's nothing particularly different about this one. I've always felt the same. The World Cup was a stage I dreamed of since childhood. I think each day will be precious. I'll do my best in the remaining time. If I play, I hope it will be an enjoyable time. Of course we have to achieve results, but I want to spend enjoyable time with the players rather than suffering under pressure. I want pasar un buen rato delante de tantos ciudadanos que nos apoyan”. Se le conoce cariñosamente como “Strawberry Milk” gracias a un animado espectáculo de baile con el grupo de chicas en una ceremonia de premios de la K League.","en":"A genuine South Korea legend with over 100 caps. He traded his K League MVP status for Germany in 2018, joining Holstein Kiel before moving to Mainz in 2021. Despite his slender frame he is a formidable aerial specialist, a prolific scorer with his head. He knows time is catching up with him, and said in March: “It's the last and my third World Cup, but there's nothing particularly different about this one. I've always felt the same. The World Cup was a stage I dreamed of since childhood. I think each day will be precious. I'll do my best in the remaining time. If I play, I hope it will be an enjoyable time. Of course we have to achieve results, but I want to spend enjoyable time with the players rather than suffering under pressure. I want to have a good time in front of the many citizens who support us.” He’s known affectionately as “Strawberry Milk” thanks to a spirited dance performance with the girl group at a K League awards ceremony."}, special: "Legend" },
  { number: 20, name: 'Yang Hyun-jun', position: 'MF', age: 24, club: 'Celtic', bio: {"es":"Yang se catapultó a la fama durante el verano de 2022. Al participar en el All-Stars de la K League contra el Tottenham durante la gira de pretemporada del club de la Premier League por Corea del Sur, el complicado extremo dejó a Eric Dier persiguiendo sombras antes de desatar un ataque feroz: un momento decisivo para poner su nombre en el mapa. La eventual convocatoria de Yang a la selección absoluta fue recibida con una divertida bienvenida por parte de Lee Kang-in del PSG. Habiendo ocupado el puesto de jugador más joven del equipo hasta la llegada de Yang, Lee bromeó diciendo que estaba encantado de tener finalmente \"alguien nuevo a quien burlarse\". Un movimiento de alto perfil a Europa atrajo en el verano de 2023, con Yang sellando una transferencia al Celtic. La medida lo vio unirse con su compatriota Oh Hyeon-gyu, y el dúo ahora está preparado para mostrar su sinergia en el escenario más grandioso de todos en esta Copa Mundial. Si bien es un extremo por naturaleza, Yang ha demostrado recientemente su versatilidad táctica, desplegado como un lateral dinámico para el club y el país.","en":"Yang catapulted himself into the spotlight during the summer of 2022. Turning out for the K League All-Stars against Tottenham during the Premier League club’s pre-season tour of South Korea, the tricky winger left Eric Dier chasing shadows before unleashing a ferocious strike – a breakthrough moment to put his name on the map. Yang’s eventual call-up to the senior national team was met with a playful welcome from PSG’s Lee Kang-in. Having held the mantle of the squad's youngest player until Yang's arrival, Lee quipped that he was delighted to finally have \"someone new to tease\". A high-profile move to Europe beckoned in the summer of 2023, with Yang sealing a transfer to Celtic. The move saw him link up with compatriot Oh Hyeon-gyu, and the duo are now primed to showcase their synergy on the grandest stage of all at this World Cup. While naturally an out-and-out winger, Yang has recently demonstrated his tactical versatility, deployed as a dynamic wing-back for club and country."}, special: "Tactically astute" },
  { number: 24, name: 'Kim Jin-gyu', position: 'MF', age: 29, club: 'Jeonbuk Hyundai Motors', bio: {"es":"La carrera internacional de Kim no podría haber comenzado mucho mejor: anotó en sus dos primeras apariciones en 2022. Pero fue un amanecer falso: cayó en desgracia y le tomó la asombrosa cantidad de 34 meses regresar a la configuración absoluta después de su última participación en julio de 2022. Fue solo bajo la dirección de Gus Poyet en Jeonbuk el año pasado que su juego completo mejoró lo suficiente como para obligar a un retiro. Debería ser un activo para el equipo este verano, con sólidos pases hacia adelante y una amenaza en las jugadas a balón parado. Le dijo al Korea Times en marzo: \"Cuando se trata de hacer pases agresivos y gestionar jugadas, siempre me he sentido seguro de que puedo ser tan bueno como cualquiera. Desde que comencé a ser convocado con más frecuencia el año pasado, comencé a soñar con formar parte del equipo de la Copa Mundial\".","en":"Kim’s international career could not have started much better: he scored in both his first two appearances in 2022. But it was a false dawn: he fell out of favour and it took a staggering 34 months for him to return to the senior setup after his last involvement in July 2022. It was only under the guidance of Gus Poyet at Jeonbuk last year that his all-round game improved enough to force a recall. He should be an asset to the squad this summer, with solid forward passing and a threat from set-pieces. He told the Korea Times in March: “When it comes to making aggressive passes and managing plays, I've always felt confident that I can be as good as anybody. Since I started getting called up more frequently last year, I began dreaming about making the World Cup team.”"} },
  { number: 26, name: 'Lee Dong-gyeong', position: 'MF', age: 28, club: 'Ulsan Hyundai', bio: {"es":"Él y Lee Kang-in son los dos jugadores zurdos más clínicos de la selección nacional. Se unió a Ulsan Hyundai después de abandonar la universidad en 2018 y desde entonces ha estado cedido en Alemania con Schalke y Hansa Rostock. El año pasado, mientras completaba su servicio militar, fue nombrado Jugador del Año de la K League 1 por sus actuaciones con Gimcheon Sangmu, el club militar de la división. Su apodo, Tokyo Lee, juega con su nombre de pila, Dong-gyeong, que comparte la misma pronunciación que la palabra coreana para Tokio. Lee, que nació exactamente un año después de su compañero de equipo Hwang In-beom, habló en enero sobre su gran ambición profesional: \"Es jugar en mi primera Copa del Mundo. He alineado todo, mi mentalidad y mi condición, hacia la Copa del Mundo... Hay muchas más cosas que aún no he demostrado. Quiero abrir de par en par las puertas a la cima de mi carrera futbolística\".","en":"He and Lee Kang-in are the two most clinical left-footed players in the national side. He joined Ulsan Hyundai after dropping out of university in 2018, and has since had loan spells in Germany with Schalke and Hansa Rostock. Last year, while completing his military service, he was named K League 1 Player of the Year for his performances with Gimcheon Sangmu, the division’s military club. His nickname, Tokyo Lee, plays on his given name, Dong-gyeong, which shares the same pronunciation as the Korean word for Tokyo. Lee, who was born exactly one year after teammate Hwang In-beom, spoke in January about his one big career ambition: “It is to play in my first World Cup. I’ve aligned everything, my mindset and my condition, towards the World Cup … There’s a lot more I haven’t shown yet. I want to throw the doors wide open to the prime of my football career.”"} },
  // Delanteros
  { number: 7, name: 'Son Heung-min', position: 'FW', age: 33, club: 'Los Angeles FC', bio: {"es":"2025 fue un gran año para Son. Como el capitán que finalmente rompió la maldición de los trofeos del Tottenham, terminó una década en el norte de Londres con un traslado de £20 millones a Los Ángeles –un récord de la MLS– en medio de una tormenta de marketing de “este contra oeste” que enfrentaba a Lionel Messi en la Conferencia Este contra Son en la Oeste. Sigue siendo un talento excelente, aunque hubo algunas críticas en el período previo a la Copa del Mundo de que ha comenzado a perder su ventaja. Son respondió: \"No creo que haya sufrido ningún descenso en mi rendimiento. Es decepcionante que la gente hable de descenso cada vez que tengo un período de sequía. Sé que hay grandes expectativas puestas en mí porque he marcado muchos goles a lo largo de los años. Siempre estoy haciendo lo mejor que puedo y me siento bien físicamente\". En 2022 lanzó su propia marca de moda, NOS7, que significa “Nada, Domingo Ordinario”, con el espíritu de la marca centrado en la reflexión y la calma durante el fin de semana: “Fin de semana después de una semana ocupada, compartimos ese precioso momento”.","en":"2025 was a big year for Son. As the captain who finally broke Tottenham’s trophy curse, he ended a decade in North London with a £20m move to Los Angeles – an MLS record – amid a blizzard of “east versus west” marketing pitting Lionel Messi in the Eastern Conference versus Son in the Western. He remains a superb talent, though there was some criticism in the build-up to the World Cup that he has started losing his edge. Son hit back, saying: “I don't think I've suffered any dip in my performance. It's disappointing that people talk about decline whenever I hit a dry spell. I know there are high expectations on me because I've scored so many goals over the years. I am always doing the best I can, and I am feeling good physically.\" In 2022 he launched his own fashion brand, NOS7, standing for “Nothing, Ordinary Sunday”, with the brand ethos focused on reflection and calm at the weekend: “Weekend after a busy week, we share that precious moment.”"}, special: "Superstar" },
  { number: 9, name: 'Cho Gue-sung', position: 'FW', age: 28, club: 'FC Midtjylland', bio: {"es":"El camino de Cho para convertirse en delantero internacional comenzó tarde, durante su primer año en la Universidad de Gwangju, cuando pasó al frente desde su posición normal de mediocampo defensivo. Llamó la atención en 2019 cuando marcó 14 goles para el FC Anyang en la K League 2, pero su transición a la máxima categoría con el Jeonbuk en 2020 fue una lucha. Fue durante su servicio militar que redescubrió su toque goleador, demostrando ser prolífico durante 2021-22 con el Gimcheon Sangmu militar de la K League 1, y también actuando a nivel internacional, marcando dos goles contra Ghana en el Mundial de Qatar, que más tarde calificó como “el mejor momento de mi vida”. Se unió al Midtjylland danés en 2023, alcanzando cifras dobles en su primera temporada, pero luego se perdió toda la temporada siguiente debido a complicaciones con su cirugía de rodilla. Hizo su regreso en agosto del año pasado después de una agotadora pausa de 448 días. \"Cuando me di cuenta por primera vez de la gravedad de mi lesión, la situación era obviamente difícil, pero rápidamente decidí empezar de nuevo\", dijo el año pasado. “Esa era mi mentalidad, porque mi estilo de vida no se trata de arrepentirme de cosas del pasado… No soy una persona emocional”.","en":"Cho’s journey to becoming an international striker began late, during his first year at Gwangju University, when he moved up front from his normal defensive midfield position. He caught the eye in 2019 as he scored 14 goals for FC Anyang in K League 2, but his transition to the top-flight with Jeonbuk in 2020 was a struggle. It was during his military service that he rediscovered his scoring touch, proving prolific during 2021-22 with K League 1 military side Gimcheon Sangmu, and performing at international level too, scoring twice against Ghana at the Qatar World Cup, which he later called “the best moment of my life”. He joined Danish side Midtjylland in 2023, hitting double figures in his first season, but then missing the whole of the following season after complications with his knee surgery. He made his comeback in August last year after a gruelling 448-day hiatus. “When I first realised how serious my injury was, the situation was obviously difficult, but I quickly decided to just start afresh,” he said last year. “That was my mentality, because my lifestyle is not about regretting things from the past … I’m not an emotional person.”"} },
  { number: 11, name: 'Hwang Hee-chan', position: 'FW', age: 30, club: 'Wolves', bio: {"es":"Al igual que Son Heung-min, Hwang comenzó su carrera profesional en Europa, lo cual es inusual para los jugadores surcoreanos. Pasó del Red Bull Salzburg al RB Leipzig en 2020, luego a los Wolves en 2022 después de una exitosa cesión. Su apodo, The Bull, es un guiño tanto a su primer club como a su estilo de juego agresivo. Saltó a la fama internacional durante su estancia en Salzburgo, y marcó un gol contra el Liverpool en Anfield en la Liga de Campeones. Mantiene una estrecha amistad con su excompañero, Erling Haaland. En un amistoso de Corea del Sur en 2020 contra Qatar, anotó solo 16 segundos después del saque inicial, estableciendo el récord del gol más rápido en la historia internacional de Corea del Sur. En 2023, el técnico del Manchester City, Pep Guardiola, fue criticado por referirse a él como “el chico coreano” en lugar de por su nombre antes de un partido contra los Wolves; Hwang respondió anotando el gol de la victoria al día siguiente. Más tarde dijo: \"Escuché 'el chico coreano' y algunas personas tenían opiniones negativas. Pero yo siempre pienso en positivo. Lo usé para motivarme mucho\".","en":"Like Son Heung-min, Hwang began his professional career in Europe, which is unusual for South Korean players. He moved from Red Bull Salzburg to RB Leipzig in 2020, then to Wolves in 2022 after a successful loan spell. His nickname, The Bull, is a nod to both his first club and his aggressive playing style. He rose to international prominence during his time at Salzburg, famously scoring against Liverpool at Anfield in the Champions League. He maintains a close friendship with his former teammate, Erling Haaland. In a 2020 South Korea friendly against Qatar he scored just 16 seconds after kickoff, setting the record for the fastest goal in South Korean international history. In 2023, Manchester City manager Pep Guardiola was criticised for referring to him as “the Korean guy” rather than by name before a match against Wolves; Hwang responded by scoring the winner the following day. He said later: “I heard ‘the Korean guy’, and some people had negative views. But I always think positively. I used it to motivate myself a lot.”"}, special: "Creative powerhouse" },
  { number: 17, name: 'Bae Jun-ho', position: 'FW', age: 22, club: 'Stoke City', bio: {"es":"Un extremo veloz que combina la industria de Park Ji-sung con la astucia técnica de Lee Chung-yong. Ha sido visto como el heredero natural de Son Heung-min y Hwang Hee-chan en el flanco izquierdo desde que apareció en los titulares por primera vez en la semifinal de Corea del Sur en la Copa Mundial Sub-20 de 2023. A pesar de marcar en su debut internacional absoluto en 2024, ha estado entrando y saliendo del equipo desde entonces, pero sus actuaciones en Inglaterra con el Stoke lo mantuvieron en la contienda para este verano. Después de ganar el premio al jugador del año en su primera temporada en Stoke en 2023-24, habló sobre el proceso de adaptación y dijo: \"Antes de aprender el idioma era muy difícil. Era más fácil cuando podía comunicarme hasta cierto punto. Lo primero que aprendí fue a decir malas palabras, así que pude decir libremente lo que pensaba\". En marzo de este año, el entrenador de su club, Mark Robins, dijo que todo lo que Bae necesita agregar a su juego son más goles \"para llevarlo al nivel más alto, y es capaz de hacerlo. Tiene muchísimos buenos atributos... está ahí, todo ahí, sólo tenemos que unirlo todo más a menudo\".","en":"A pacey winger who blends the industry of Park Ji-sung with the technical guile of Lee Chung-yong. He has been seen as the natural heir to Son Heung-min and Hwang Hee-chan on the left flank since he first made headlines in South Korea’s semi-final run at the 2023 U-20 World Cup. Despite scoring on his senior international debut in 2024 he has been in and out of the squad since, but his displays in England with Stoke kept him in contention for this summer. After winning player of the year in his first season at Stoke in 2023-24 he talked about the process of settling in, saying: “Before I learned the language it was very difficult. It was easier when I was able to communicate to a certain extent. The first thing I learned was swearing so I was able to freely say what I thought.” In March this year his club manager, Mark Robins, said all Bae needs to add to his game is more goals “to take him to the top level – and he’s capable of doing that. He’s got loads and loads of good attributes … it’s there, all there, we’ve just got to put it all together more often.”"} },
  { number: 18, name: 'Oh Hyeon-gyu', position: 'FW', age: 24, club: 'Besiktas', bio: {"es":"Producto de la academia juvenil de Suwon Samsung Bluewings, la resistencia de Oh se puso a prueba desde el principio cuando una lesión del ligamento cruzado lo dejó fuera de juego durante casi un año entero durante su primer año de escuela secundaria. Fue un largo camino atrás, pero hizo su debut profesional con Suwon en 2019, luego se convirtió en un héroe del club en 2022 cuando anotó el dramático gol de la victoria en la prórroga en los playoffs de ascenso y descenso, un momento que dejó al joven delantero llorando a mares. Una vez completado el servicio militar obligatorio, se fue a Europa, primero al Celtic en 2023 y luego al Genk un año después. El verano pasado, una propuesta de mudanza de £ 28 millones a Stuttgart fracasó cuando no pasó el examen médico, pero en febrero completó una mudanza de £ 12 millones a Turquía. En marzo reflexionó sobre su paso por el Celtic, su primera experiencia en Europa y su lucha contra la nostalgia. \"Cuando estaba en el Celtic había una canción que solía escuchar con bastante frecuencia, especialmente cuando las cosas se ponían un poco difíciles. Esa era la canción Take Me Home, Country Roads. La escuchaba mucho. Me reconfortaba un poco y a menudo me hacía pensar en lo mucho que deseaba volver a casa. Pero últimamente no he tenido ganas de escucharla\".","en":"A product of Suwon Samsung Bluewings' youth academy, Oh’s resilience was tested early on when a cruciate ligament injury sidelined him for nearly an entire year during his first year of high school. It was a long way back, but he made his professional debut with Suwon in 2019, then made himself a club hero in 2022 when he scored the dramatic extra-time winner in the promotion-relegation playoffs, a moment that left the young striker in floods of tears. Having completed his mandatory military service he left for Europe, first to Celtic in 2023, then to Genk a year later. Last summer a proposed £28m move to Stuttgart fell through when he failed the medical, but in February he completed a £12m move to Turkey. In March he reflected on his time at Celtic, his first experience of Europe, and his struggle with homesickness. “When I was at Celtic there was a song I used to listen to quite often, especially when things got a bit tough. That was the song Take Me Home, Country Roads. I listened to it a lot. It gave me some comfort, and it often made me think about how much I wanted to go home. But I haven’t really felt like listening to it lately.”"} },
  { number: 19, name: 'Lee Kang-in', position: 'FW', age: 25, club: 'Paris St-Germain', bio: {"es":"Ampliamente reconocido como uno de los mejores atacantes zurdos de la historia de Corea del Sur. Lee se hizo famoso por primera vez con sólo seis años cuando protagonizó el reality show de fútbol Fly Shoot Dori, que unía a niños con ex profesionales mientras aprendían el juego. “Gané el programa”, dijo el año pasado. \"Hice muchos amigos allí y tengo buenos recuerdos de ello... Los entrenadores me inculcaron la idea de no perder balones fáciles y tratar de jugar hacia adelante. Me encanta el fútbol desde que era niño, al igual que mi familia\". Se mudó a España a los 10 años para unirse a la academia juvenil de Valencia y progresó rápidamente en las filas. Hizo su debut en un club absoluto a los 17 años y luego ganó el Balón de Oro en la Copa Mundial Sub-20 de la FIFA de 2019. That same year he won Asian Young Footballer of the Year, and made his senior international debut. Se unió al Paris Saint-Germain por £18 millones en 2023, donde se convirtió en el primer jugador asiático en ganar un triplete continental.","en":"Widely acknowledged as one of the finest left-footed attackers in South Korean history. Lee first became famous aged just six when he starred in the reality football TV show Fly Shoot Dori which paired kids with former professionals as they learned the game. “I won the show,” he said last year. “I made a lot of friends there, and I have fond memories of it … The coaches instilled in me the idea of not losing easy balls and trying to play forward. I've loved football since I was a child, and so has my family.” He moved to Spain aged 10 to join the Valencia youth academy and made rapid progress through the ranks. He made his senior club debut at 17, then won the Golden Ball at the 2019 Fifa under-20 World Cup. That same year he won Asian Young Footballer of the Year, and made his senior international debut. He joined Paris Saint-Germain for £18m in 2023 where he became the first Asian player to win a continental treble."} },
  { number: 25, name: 'Eom Ji-sung', position: 'FW', age: 23, club: 'Swansea City', bio: {"es":"Eom, un extremo veloz capaz de operar en ambos flancos, es producto de la misma escuela secundaria que crió a la ex estrella de Swansea, Ki Sung-yueng. Cuando Eom se mudó a Gales en 2024 procedente del club Gwangju FC de la K League 1, dijo: \"Ki se puso en contacto conmigo y hablamos por teléfono. Fue de gran ayuda porque Ki me animó, me dijo que trabajara duro y me dijo que me adaptaría bien. Yo era joven cuando él jugaba en el Swansea, así que no recuerdo mucho, pero sí recuerdo algunos fantásticos tiros de media distancia y goles. Desde que era joven, soñaba con emular a jugadores como Ki Sung-yueng y Park Ji-sung, y creo que esa fue la fuerza impulsora que me llevó a donde estoy ahora. Creo que por eso pude aprovechar esta gran oportunidad”. Famoso por utilizar la famosa celebración con la cámara de Son Heung-min, debe su nombre a que sus padres eran fanáticos devotos de Park Ji-sung.","en":"A pacey winger able to operate on both flanks, Eom is a product of the same high school that nurtured the former Swansea star Ki Sung-yueng. When Eom moved to Wales in 2024 from K League 1 club Gwangju FC he said: “Ki contacted me and we spoke on the phone. It was a big help because Ki cheered me on, told me to work hard, and told me that I would adapt well. I was young at the time when he played for Swansea, so I don't remember much, but I do remember some fantastic mid-range shots and goals. Since I was young, I dreamed of emulating players like Ki Sung-yueng and Park Ji-sung, and I think that was the driving force that brought me to where I am now. I think that’s why I was able to seize such a great opportunity.” Famous for using Son Heung-min’s famous camera celebration, he owes his name to having parents who were devoted fans of Park Ji-sung."}, special: "One to watch" },
];

export const lineup = {
  formation: '3-4-3',
  startingXI: [21, 2, 4, 9, 22, 6, 10, 13, 19, 7, 11]
};
